slice-a-object-count.sourceCode:
// The number of tracks in each message of the tracker, for the plot.
export const inputs = ["/perception/object_recognition/tracking/objects"];
export const output = "/studio_script/slice_a/object_count";

type Output = { count: number };

export default function script(event: { message: { objects: unknown[] } }): Output {
  return { count: event.message.objects.length };
}

isuzu-ego.sourceCode:
// Isuzu localization (#110): the bus and its trail in map, from the EKF's odometry.
// The bus is a box approximated from the bag's sensor mounts, not its drawings: the sensor
// kit sits 6.2 m ahead of base_link at the front, the side lidars 1.27 m left and right.
// The trail keeps the EKF's positions; it starts again when the player loops and time
// goes back.
import { CubePrimitive, LinePrimitive, LineType, SceneUpdate, TextPrimitive } from "@foxglove/schemas";

export const inputs = ["/localization/pose_twist_fusion_filter/kinematic_state"];
export const output = "/studio_script/isuzu/ego";

type Time = { sec: number; nsec: number };
type Odometry = {
  header: { stamp: Time; frame_id: string };
  pose: { pose: { position: { x: number; y: number; z: number } } };
  twist: { twist: { linear: { x: number } } };
};

// The bus, in base_link: from 3.0 m behind to 6.5 m ahead, 2.5 m wide, 3.0 m high.
const REAR = 3.0;
const FRONT = 6.5;
const WIDTH = 2.5;
const HEIGHT = 3.0;
// Trail points kept: a minute at 50 Hz.
const TRAIL = 3000;

let trail: { x: number; y: number; z: number }[] = [];
let lastNanos = -Infinity;

export default function script(event: { message: Odometry }): SceneUpdate {
  const odom = event.message;
  const stamp = odom.header.stamp;
  const nanos = stamp.sec * 1e9 + stamp.nsec;
  if (nanos < lastNanos) {
    trail = [];
  }
  lastNanos = nanos;
  const p = odom.pose.pose.position;
  trail.push({ x: p.x, y: p.y, z: p.z });
  if (trail.length > TRAIL) {
    trail = trail.slice(trail.length - TRAIL);
  }
  const speed = odom.twist.twist.linear.x;
  const identity = { x: 0, y: 0, z: 0, w: 1 };
  const bus: CubePrimitive = {
    pose: { position: { x: (FRONT - REAR) / 2, y: 0, z: HEIGHT / 2 }, orientation: identity },
    size: { x: FRONT + REAR, y: WIDTH, z: HEIGHT },
    color: { r: 0.98, g: 0.8, b: 0.18, a: 0.35 },
  };
  const label: TextPrimitive = {
    pose: { position: { x: 0, y: 0, z: HEIGHT + 1.2 }, orientation: identity },
    billboard: true,
    font_size: 14,
    scale_invariant: true,
    color: { r: 1, g: 0.92, b: 0.55, a: 1 },
    text: `Isuzu bus  ${(speed * 3.6).toFixed(1)} km/h`,
  };
  const path: LinePrimitive = {
    type: LineType.LINE_STRIP,
    pose: { position: { x: 0, y: 0, z: 0 }, orientation: identity },
    thickness: 0.35,
    scale_invariant: false,
    points: trail,
    color: { r: 0.98, g: 0.8, b: 0.18, a: 0.9 },
    colors: [],
    indices: [],
  };
  const entity = (id: string, frame: string) => ({
    timestamp: stamp,
    frame_id: frame,
    id,
    lifetime: { sec: 0, nsec: 0 },
    frame_locked: true,
    metadata: [],
    arrows: [],
    cubes: [],
    spheres: [],
    cylinders: [],
    lines: [],
    triangles: [],
    texts: [],
    models: [],
  });
  const busEntity = { ...entity("bus", "base_link"), cubes: [bus], texts: [label] };
  const trailEntity = { ...entity("trail", "map"), lines: [path] };
  return { deletions: [], entities: [busEntity, trailEntity] };
}

tracking-tracks.sourceCode:
// Tracking (#114): the multi-object tracker's tracks in map, as Foxglove shows no
// autoware_perception_msgs. A track is a box: the smallest rectangle around its footprint
// (shape estimation's convex hull), or its own box or cylinder, extruded to its height
// about its pose, in a colour fixed by its id,
// with a label (short id, speed) and an arrow along its velocity when it moves.
import { ArrowPrimitive, LinePrimitive, LineType, SceneUpdate, TextPrimitive, TriangleListPrimitive } from "@foxglove/schemas";

export const inputs = ["/perception/object_recognition/tracking/objects"];
export const output = "/studio_script/tracking/tracks";

type Vec3 = { x: number; y: number; z: number };
type Quat = { x: number; y: number; z: number; w: number };
type Track = {
  object_id: { uuid: Uint8Array | number[] };
  existence_probability: number;
  kinematics: {
    pose_with_covariance: { pose: { position: Vec3; orientation: Quat } };
    twist_with_covariance: { twist: { linear: Vec3 } };
  };
  shape: { type: number; footprint: { points: Vec3[] }; dimensions: Vec3 };
};
type Tracks = { header: { stamp: { sec: number; nsec: number }; frame_id: string }; objects: Track[] };

// Speed below which a track shows no arrow, in m/s.
const MOVING = 0.5;
const BOX = 0;
const CYLINDER = 1;

function hue(id: Uint8Array | number[]): { r: number; g: number; b: number } {
  const h = ((id[0] ?? 0) * 256 + (id[1] ?? 0)) / 65536;
  const k = (n: number) => (n + h * 6) % 6;
  const f = (n: number) => 0.85 - 0.6 * Math.max(0, Math.min(k(n), 4 - k(n), 1));
  return { r: f(5), g: f(3), b: f(1) };
}

function footprint(shape: Track["shape"]): Vec3[] {
  const d = shape.dimensions;
  if (shape.type === BOX) {
    const x = d.x / 2;
    const y = d.y / 2;
    return [{ x, y, z: 0 }, { x: -x, y, z: 0 }, { x: -x, y: -y, z: 0 }, { x, y: -y, z: 0 }];
  }
  if (shape.type === CYLINDER) {
    const r = d.x / 2;
    return Array.from({ length: 16 }, (_, i) => {
      const a = (i / 16) * 2 * Math.PI;
      return { x: r * Math.cos(a), y: r * Math.sin(a), z: 0 };
    });
  }
  return rectangle(shape.footprint.points);
}

// The smallest rectangle around a footprint, its angle searched in 1 degree steps: a
// display aid, as the tracker tracks the footprint itself.
function rectangle(points: Vec3[]): Vec3[] {
  if (points.length < 3) {
    return points;
  }
  let best = { area: Infinity, a: 0, u0: 0, u1: 0, v0: 0, v1: 0 };
  for (let degrees = 0; degrees < 90; degrees++) {
    const a = (degrees * Math.PI) / 180;
    const c = Math.cos(a);
    const s = Math.sin(a);
    let u0 = Infinity, u1 = -Infinity, v0 = Infinity, v1 = -Infinity;
    for (const p of points) {
      const u = p.x * c + p.y * s;
      const v = -p.x * s + p.y * c;
      u0 = Math.min(u0, u); u1 = Math.max(u1, u);
      v0 = Math.min(v0, v); v1 = Math.max(v1, v);
    }
    const area = (u1 - u0) * (v1 - v0);
    if (area < best.area) {
      best = { area, a, u0, u1, v0, v1 };
    }
  }
  const c = Math.cos(best.a);
  const s = Math.sin(best.a);
  const corner = (u: number, v: number) => ({ x: u * c - v * s, y: u * s + v * c, z: 0 });
  return [corner(best.u0, best.v0), corner(best.u1, best.v0), corner(best.u1, best.v1), corner(best.u0, best.v1)];
}

export default function script(event: { message: Tracks }): SceneUpdate {
  const tracks = event.message;
  const stamp = tracks.header.stamp;
  const entities = tracks.objects.map((track, index) => {
    const id = Array.from(track.object_id.uuid);
    const shortId = id.slice(0, 2).map((b) => b.toString(16).padStart(2, "0")).join("");
    const rgb = hue(id);
    const pose = track.kinematics.pose_with_covariance.pose;
    const height = Math.max(track.shape.dimensions.z, 0.3);
    const ring = footprint(track.shape);
    const bottom = ring.map((p) => ({ x: p.x, y: p.y, z: -height / 2 }));
    const top = ring.map((p) => ({ x: p.x, y: p.y, z: height / 2 }));
    const outline: Vec3[] = [];
    for (let i = 0; i < ring.length; i++) {
      const j = (i + 1) % ring.length;
      outline.push(bottom[i], bottom[j], top[i], top[j], bottom[i], top[i]);
    }
    const faces: Vec3[] = [];
    for (let i = 1; i + 1 < ring.length; i++) {
      faces.push(top[0], top[i], top[i + 1]);
    }
    for (let i = 0; i < ring.length; i++) {
      const j = (i + 1) % ring.length;
      faces.push(bottom[i], bottom[j], top[j], bottom[i], top[j], top[i]);
    }
    const v = track.kinematics.twist_with_covariance.twist.linear;
    const speed = Math.hypot(v.x, v.y);
    const color = { ...rgb, a: 1 };
    const lines: LinePrimitive[] = [{
      type: LineType.LINE_LIST, pose, thickness: 0.06, scale_invariant: false,
      points: outline, color, colors: [], indices: [],
    }];
    const triangles: TriangleListPrimitive[] = [{
      pose, points: faces, color: { ...rgb, a: 0.25 }, colors: [], indices: [],
    }];
    const texts: TextPrimitive[] = [{
      pose: { position: { x: pose.position.x, y: pose.position.y, z: pose.position.z + height / 2 + 0.8 },
              orientation: { x: 0, y: 0, z: 0, w: 1 } },
      billboard: true, font_size: 12, scale_invariant: true, color,
      text: speed >= MOVING ? `#${shortId} ${(speed * 3.6).toFixed(0)} km/h` : `#${shortId}`,
    }];
    // The twist is in the track's own frame: the arrow points along it from the pose.
    const arrows: ArrowPrimitive[] = speed >= MOVING ? [{
      pose: { position: pose.position, orientation: pose.orientation },
      shaft_length: Math.min(speed, 10) * 0.5, shaft_diameter: 0.15,
      head_length: 0.5, head_diameter: 0.4, color,
    }] : [];
    return {
      timestamp: stamp, frame_id: tracks.header.frame_id, id: `track-${index}`,
      lifetime: { sec: 0, nsec: 0 }, frame_locked: false, metadata: [],
      arrows, cubes: [], spheres: [], cylinders: [], lines, triangles, texts, models: [],
    };
  });
  // Each message replaces the tracks of the one before: no lifetime, which would count
  // from the stamp and expire tracks whose stamp lags the viewer's clock.
  return { deletions: [{ timestamp: stamp, type: 1, id: "" }], entities };
}
